import { evaluate } from "@/lib/content/expr";
import { clean, fmt, isWhole, makeRng, pick, seedFromString, type Rng } from "./rng";
import type { NumericDrill } from "./types";

// Mental-maths drills are generated by code (kit section 7). Each family builds
// questions from numbers that work well in your head. Every drill records the
// expression and inputs it came from, and the tests recompute the answer with
// the safe evaluator (rule 2.9).

type Made = {
  prompt: string;
  unit: string;
  inputs: Record<string, number>;
  expression: string;
  tolerancePct: number;
  explain: (answer: number) => string;
};

type Family = { key: string; title: string; make: (rng: Rng) => Made | null };

const PER_FAMILY = 20;

const families: Family[] = [
  {
    key: "percent-of",
    title: "Percentage of a number",
    make(rng) {
      const pct = pick(rng, [5, 10, 12.5, 15, 20, 25, 30, 40, 60, 75, 80]);
      const base = pick(rng, [40, 80, 120, 160, 200, 240, 320, 400, 480, 800, 1200, 2000, 2400]);
      return {
        prompt: `What is ${fmt(pct)}% of ${fmt(base)}?`,
        unit: "",
        inputs: { base, pct },
        expression: "base * pct / 100",
        tolerancePct: 1,
        explain: (a) => `${fmt(pct)}% of ${fmt(base)} = ${fmt(base)} x ${fmt(pct)} / 100 = ${fmt(a)}. Tip: start from 10% (move the decimal) and build up.`,
      };
    },
  },
  {
    key: "percent-change",
    title: "Percentage change",
    make(rng) {
      const old_value = pick(rng, [40, 50, 60, 80, 100, 120, 200, 250, 400]);
      const pct = pick(rng, [5, 10, 15, 20, 25, 30, 40, 50, 60, 75]);
      const up = rng() < 0.5;
      const next = old_value * (1 + (up ? pct : -pct) / 100);
      if (!isWhole(next)) return null;
      const new_value = clean(next);
      return {
        prompt: `Sales ${up ? "rose" : "fell"} from $${fmt(old_value)}m to $${fmt(new_value)}m. By what percentage did they ${up ? "rise" : "fall"}?`,
        unit: "%",
        inputs: { old_value, new_value },
        expression: up ? "(new_value - old_value) / old_value * 100" : "(old_value - new_value) / old_value * 100",
        tolerancePct: 1,
        explain: (a) => `Change / starting value = ${fmt(Math.abs(new_value - old_value))} / ${fmt(old_value)} = ${fmt(a)}%. Always divide by the starting value.`,
      };
    },
  },
  {
    key: "big-multiply",
    title: "Multiplying large numbers",
    make(rng) {
      const units_k = pick(rng, [800, 1200, 1500, 2000, 2500, 3000, 3500, 4000, 4500, 6000, 7500, 8000]);
      const price = pick(rng, [12, 15, 20, 25, 30, 40, 50, 60, 80, 120]);
      return {
        prompt: `A product sells ${fmt(units_k / 1000)} million units at $${fmt(price)} each. What is the revenue, in $ million?`,
        unit: "$ million",
        inputs: { units_k, price },
        expression: "units_k * price / 1000",
        tolerancePct: 1,
        explain: (a) => `${fmt(units_k / 1000)} million x $${fmt(price)} = $${fmt(a)} million. Multiply the digits, then place the millions.`,
      };
    },
  },
  {
    key: "division",
    title: "Dividing to get a rate",
    make(rng) {
      const days = pick(rng, [4, 5, 8, 10, 12, 15, 20, 25]);
      const per_day = pick(rng, [150, 200, 250, 400, 500, 750, 1200, 1500, 2000, 3000]);
      const total = days * per_day;
      return {
        prompt: `A factory makes ${fmt(total)} units over ${fmt(days)} days. How many units does it make per day?`,
        unit: "units",
        inputs: { total, days },
        expression: "total / days",
        tolerancePct: 1,
        explain: (a) => `${fmt(total)} / ${fmt(days)} = ${fmt(a)} per day. Simplify first: halve or divide both numbers by ${fmt(days / (days % 5 === 0 ? 5 : days % 4 === 0 ? 4 : 1))} if it helps.`,
      };
    },
  },
  {
    key: "fraction-percent",
    title: "Turning a part into a percentage",
    make(rng) {
      const whole = pick(rng, [20, 25, 40, 50, 60, 72, 80, 120, 150, 200, 250, 400]);
      const pct = pick(rng, [5, 10, 12.5, 15, 20, 25, 30, 40, 50, 60, 75]);
      const part = (whole * pct) / 100;
      if (!isWhole(part)) return null;
      return {
        prompt: `What percentage of ${fmt(whole)} is ${fmt(part)}?`,
        unit: "%",
        inputs: { part, whole },
        expression: "part / whole * 100",
        tolerancePct: 1,
        explain: (a) => `${fmt(part)} / ${fmt(whole)} = ${fmt(a / 100)}, which is ${fmt(a)}%.`,
      };
    },
  },
  {
    key: "compound-growth",
    title: "Growth over two years",
    make(rng) {
      const start = pick(rng, [100, 150, 200, 250, 400, 500, 800, 1000]);
      const rate = pick(rng, [10, 20, 50]);
      return {
        prompt: `Revenue is $${fmt(start)}m and grows ${rate}% a year. What is revenue after 2 years, in $ million?`,
        unit: "$ million",
        inputs: { start, rate },
        expression: "start * (1 + rate / 100) ^ 2",
        tolerancePct: 1,
        explain: (a) => `Year 1: ${fmt(start)} x ${fmt(1 + rate / 100)} = ${fmt(start * (1 + rate / 100))}. Year 2: x ${fmt(1 + rate / 100)} again = ${fmt(a)}. Do not just add ${rate}% twice.`,
      };
    },
  },
  {
    key: "margin",
    title: "Profit margin",
    make(rng) {
      const revenue = pick(rng, [200, 250, 400, 500, 800, 1000, 1200]);
      const margin = pick(rng, [5, 8, 10, 12, 15, 20, 25, 30]);
      const costs = (revenue * (100 - margin)) / 100;
      if (!isWhole(costs)) return null;
      return {
        prompt: `Revenue is $${fmt(revenue)}m and total costs are $${fmt(costs)}m. What is the profit margin?`,
        unit: "%",
        inputs: { revenue, costs },
        expression: "(revenue - costs) / revenue * 100",
        tolerancePct: 1,
        explain: (a) => `Profit = ${fmt(revenue)} - ${fmt(costs)} = ${fmt(revenue - costs)}. Margin = profit / revenue = ${fmt(revenue - costs)} / ${fmt(revenue)} = ${fmt(a)}%.`,
      };
    },
  },
  {
    key: "breakeven",
    title: "Break-even volume",
    make(rng) {
      const fixed = pick(rng, [60000, 90000, 120000, 150000, 180000, 240000, 300000]);
      const price = pick(rng, [30, 40, 50, 60, 80, 100]);
      const unit_margin = pick(rng, [10, 15, 20, 25, 30, 40]);
      if (unit_margin >= price) return null;
      const units = fixed / unit_margin;
      if (!isWhole(units)) return null;
      const variable_cost = price - unit_margin;
      return {
        prompt: `Fixed costs are $${fmt(fixed)}. Each unit sells for $${fmt(price)} and costs $${fmt(variable_cost)} to make. How many units must be sold to break even?`,
        unit: "units",
        inputs: { fixed, price, variable_cost },
        expression: "fixed / (price - variable_cost)",
        tolerancePct: 1,
        explain: (a) => `Each unit contributes $${fmt(price)} - $${fmt(variable_cost)} = $${fmt(unit_margin)}. Break-even = fixed costs / contribution = ${fmt(fixed)} / ${fmt(unit_margin)} = ${fmt(a)} units.`,
      };
    },
  },
  {
    key: "market-share",
    title: "Market share",
    make(rng) {
      const market_m = pick(rng, [1200, 2000, 2400, 3000, 4000, 5000, 8000, 10000]);
      const share = pick(rng, [5, 10, 12.5, 15, 20, 25, 30]);
      const sales_m = (market_m * share) / 100;
      if (!isWhole(sales_m)) return null;
      const size = market_m >= 1000 ? `$${fmt(market_m / 1000)} billion` : `$${fmt(market_m)} million`;
      return {
        prompt: `The market is worth ${size}. A company has sales of $${fmt(sales_m)} million. What is its market share?`,
        unit: "%",
        inputs: { sales_m, market_m },
        expression: "sales_m / market_m * 100",
        tolerancePct: 1,
        explain: (a) => `Share = company sales / market = ${fmt(sales_m)} / ${fmt(market_m)} = ${fmt(a)}%. Put both in the same units first.`,
      };
    },
  },
  {
    key: "annualise",
    title: "Scaling up to a year",
    make(rng) {
      const per_day = pick(rng, [400, 500, 600, 800, 1000, 1200, 1500, 2000]);
      const price = pick(rng, [3, 4, 5, 6, 8]);
      return {
        prompt: `A cafe sells ${fmt(per_day)} coffees a day at $${fmt(price)} each and trades 350 days a year. What is its annual coffee revenue, in $ thousand?`,
        unit: "$ thousand",
        inputs: { per_day, price },
        expression: "per_day * price * 350 / 1000",
        tolerancePct: 1,
        explain: (a) => `Daily revenue = ${fmt(per_day)} x $${fmt(price)} = $${fmt(per_day * price)}. Annual = x 350 = $${fmt(per_day * price * 350)}, which is $${fmt(a)} thousand. Tip: x 350 is x 1,000 / 3 roughly, then adjust.`,
      };
    },
  },
  {
    key: "weighted-average",
    title: "Weighted average",
    make(rng) {
      const share_a = pick(rng, [20, 25, 30, 40, 50, 60, 70, 75, 80]);
      const price_a = pick(rng, [5, 8, 10, 12, 15, 20]);
      const price_b = price_a + pick(rng, [4, 8, 10, 12, 20]);
      return {
        prompt: `${fmt(share_a)}% of customers pay $${fmt(price_a)} and the other ${fmt(100 - share_a)}% pay $${fmt(price_b)}. What is the average price paid?`,
        unit: "$",
        inputs: { share_a, price_a, price_b },
        expression: "share_a / 100 * price_a + (100 - share_a) / 100 * price_b",
        tolerancePct: 1,
        explain: (a) => `Weight each price by its share: ${fmt(share_a / 100)} x ${fmt(price_a)} + ${fmt((100 - share_a) / 100)} x ${fmt(price_b)} = $${fmt(a)}. It must land between $${fmt(price_a)} and $${fmt(price_b)}, nearer the bigger group's price.`,
      };
    },
  },
  {
    key: "payback",
    title: "Payback period",
    make(rng) {
      const investment = pick(rng, [20, 30, 45, 60, 80, 90, 120, 150, 200, 240]);
      const annual_profit = pick(rng, [5, 10, 15, 20, 30, 40]);
      const years = investment / annual_profit;
      if (!isWhole(years * 2)) return null;
      return {
        prompt: `A project costs $${fmt(investment)}m and earns $${fmt(annual_profit)}m profit a year. How many years until it pays back?`,
        unit: "years",
        inputs: { investment, annual_profit },
        expression: "investment / annual_profit",
        tolerancePct: 2,
        explain: (a) => `Payback = investment / annual profit = ${fmt(investment)} / ${fmt(annual_profit)} = ${fmt(a)} years.`,
      };
    },
  },
];

function generateFamily(family: Family): NumericDrill[] {
  const rng = makeRng(seedFromString(`mental-maths:${family.key}`));
  const drills: NumericDrill[] = [];
  const seen = new Set<string>();
  let guard = 0;
  while (drills.length < PER_FAMILY && guard++ < 5000) {
    const made = family.make(rng);
    if (!made || seen.has(made.prompt)) continue;
    seen.add(made.prompt);
    const answer = clean(evaluate(made.expression, made.inputs));
    drills.push({
      id: `mm-${family.key}-${String(drills.length + 1).padStart(2, "0")}`,
      category: "mental-maths",
      kind: "numeric",
      title: family.title,
      prompt: made.prompt,
      unit: made.unit,
      answer,
      tolerancePct: made.tolerancePct,
      explanation: made.explain(answer),
      expression: made.expression,
      inputs: made.inputs,
    });
  }
  return drills;
}

/** 240 drills, interleaved so consecutive questions come from different families. */
export function generateMentalMathsDrills(): NumericDrill[] {
  const byFamily = families.map(generateFamily);
  const out: NumericDrill[] = [];
  for (let i = 0; i < PER_FAMILY; i++) {
    for (const list of byFamily) if (list[i]) out.push(list[i]);
  }
  return out;
}
